```ts
const openAndSettle = async (url: string): Promise<{client: WebSocket; frames: Frame[]; sessionId: string}> => {
  const client = open(url);
  const frames = collectFrames(client);
  const sessionId = await new Promise<string>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string};
      if (frame.type === 'connected') resolve(frame.sessionId ?? '');
    });
  });
  // A ping is a barrier: its pong can only follow every frame the server wrote before it.
  client.send(JSON.stringify({type: 'ping', timestamp: 1}));
  await waitFor(frames, frame => frame.type === 'pong');
  return {client, frames, sessionId};
};

const waitFor = async (frames: Frame[], at: (frame: Frame) => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 500 && !frames.some(at); attempt++) await new Promise(r => setTimeout(r, 10));
};
```

