```ts
// A ping sent now can only be answered with a pong written after everything already sent, so its
// arrival is a barrier: every frame the answer was going to write is in the log.
const settle = async (client: WebSocket, frames: Frame[]): Promise<void> => {
  const seen = frames.length;
  client.send(JSON.stringify({type: 'ping', timestamp: seen}));
  for (let attempt = 0; attempt < 500; attempt++) {
    if (frames.slice(seen).some(frame => frame.type === 'pong')) return;
    await new Promise(resolve => setTimeout(resolve, 10));
  }
  throw new Error(`no pong after frame ${seen}; the socket went quiet`);
};
