const open = (url: string): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  return client;
};

// Opens, and settles on a ping barrier: its pong can only be written after every frame before it.
const openAndSettle = async (url: string): Promise<{client: WebSocket; seen: Frame[]; sessionId: string}> => {
  const client = open(url);
  const seen: Frame[] = [];
  client.on('message', raw => seen.push(JSON.parse(String(raw)) as Frame));
  const sessionId = await until(seen, frame => typeof frame.sessionId === 'string', 'a connected frame').then(frame => frame.sessionId ?? '');
  await settle(client, seen);
  return {client, seen, sessionId};
};
```

