```ts
const until = async (seen: Frame[], at: (frame: Frame, at: number) => boolean, what: string): Promise<Frame> => {
  for (let attempt = 0; attempt < 500 && !seen.some(at); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
  const frame = seen.find(at);
  if (frame === undefined) throw new Error(`no ${what} arrived; the wire carried: ${seen.map(f => f.type).join(', ') || 'nothing'}`);
  return frame;
};

const settle = async (client: WebSocket, seen: Frame[]): Promise<void> => {
  const before = seen.length;
  client.send(JSON.stringify({type: 'ping', timestamp: before}));
  await until(seen, (frame, position) => position >= before && frame.type === 'pong', `a pong after frame ${before}`);
};
```

