// and read off the wire either way.
interface HistoryOptions {
  enabled: boolean;
}

type EngineConfig = Omit<HalEngineConfig, 'transport'> & {
  transport?: NonNullable<HalEngineConfig['transport']> & {history?: HistoryOptions};
};

type ServerOptions = Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'> & {history?: HistoryOptions};

