    const store = new InMemorySessionStore();
    const url = await startConfiguredEngine({
      provider: {type: 'mock'},
      prompt: {identity: 'test'},
      session: store,
      auth: {ws: async () => ({id: USER})},
      transport: {history: {enabled: true}},
    });
    const {client, seen, sessionId} = await openAndSettle(url);
    seed(store, 'earlier', USER, JAN);
    seed(store, 'later', USER, FEB);
    seed(store, 'someone-elses', SOMEONE_ELSE, FEB);

    const beforeRequest = seen.length;
    client.send(JSON.stringify({type: 'list_conversations'}));
    await until(seen, frame => frame.type === 'conversation_list' || frame.type === 'error', 'the answer to the list request');
