      ],
    });
  });

  it('answers UNSUPPORTED wherever it cannot answer, and never with a list or an empty one', async () => {
    // Off by default: the deployer never turned history on.
    const off = await startEngine({sessionStore: storeHolding([['kept', USER, JAN]])});
    const refused = await openAndSettle(off);
