  return `ws://127.0.0.1:${port}/hal/ws`;
};

const open = (url: string): WebSocket => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  return client;
};

// Resolves once the wire carries a frame answering `at`, naming what never came if it never does.
// Kept well inside jest's own test timeout, so the message below is the failure a reader sees.
const until = async (seen: Frame[], at: (frame: Frame) => boolean, what: string): Promise<Frame> => {
  for (let attempt = 0; attempt < 250 && !seen.some(at); attempt++) {
    await new Promise(resolve => setTimeout(resolve, 10));
  }
  const frame = seen.find(at);
  if (frame === undefined) {
    throw new Error(`no ${what} arrived; the wire carried: ${seen.map(f => f.type).join(', ') || 'nothing'}`);
  }
  return frame;
};

// A ping written now can only be answered after everything before it, so its pong is a barrier.
const settle = async (client: WebSocket, seen: Frame[]): Promise<void> => {
  const written = seen.length;
  client.send(JSON.stringify({type: 'ping', timestamp: written}));
  for (let attempt = 0; attempt < 250; attempt++) {
    if (seen.slice(written).some(frame => frame.type === 'pong')) return;
    await new Promise(resolve => setTimeout(resolve, 10));
  }
  throw new Error(`no pong after frame ${written}; the wire carried: ${seen.map(f => f.type).join(', ')}`);
};

// Opens, and settles once: the connected frame and any replay are all in by the time the pong is.
const openAndSettle = async (url: string): Promise<{client: WebSocket; seen: Frame[]; sessionId: string}> => {
  const client = open(url);
  const seen: Frame[] = [];
  client.on('message', raw => seen.push(JSON.parse(String(raw)) as Frame));
  const connected = await until(seen, frame => frame.type === 'connected', 'a connected frame');
  await settle(client, seen);
  return {client, seen, sessionId: connected.sessionId ?? ''};
};

// One conversation of one entry, whose activity is the moment named: the store reads it off the entry.
const seed = (store: InMemorySessionStore, id: string, user: string, activeAt: string): void => {
  const {entries} = store.create(id, user);
  entries.push({role: 'user', content: `what ${id} asked`, timestamp: activeAt});
};

const storeHolding = (conversations: Array<[id: string, user: string, activeAt: string]>): InMemorySessionStore => {
  const store = new InMemorySessionStore();
  for (const [id, user, activeAt] of conversations) seed(store, id, user, activeAt);
  return store;
};

// The real store with its calls recorded: the criterion asks for the argument, and only a recording
// store can show it while still answering the list the way a store does.
class RecordingStore extends InMemorySessionStore {
  readonly asked: Array<{userId: string | number; options: SessionListOptions | undefined}> = [];

  listFor(userId: string | number, options?: SessionListOptions): SessionSummary[] {
    this.asked.push({userId, options});
    return super.listFor(userId, options);
  }
}

// A real store in a database's failure mode: the rejection's own text names the deployment.
class FailingStore extends InMemorySessionStore {
  listFor(): Promise<SessionSummary[]> {
    return Promise.reject(new Error('mongo driver: auth failed for db-prod at cluster-eu-west'));
  }
}

// A real store that refuses to list, throwing the package's own misconfiguration error.
class CannotListStore extends InMemorySessionStore {
  listFor(): Promise<SessionSummary[]> {
    return refuseToList();
  }
}

// `StoreCannotList` is this ticket's new export, read off the package surface so this file compiles
// until it lands, and a store throws exactly what a consumer would.
const refuseToList = async (): Promise<SessionSummary[]> => {
  const surface = (await import('./index.js')) as unknown as {StoreCannotList?: new (message: string) => Error};
  if (typeof surface.StoreCannotList !== 'function') {
    throw new Error('the package exports no StoreCannotList for a store to throw');
  }
  throw new surface.StoreCannotList('this store keeps conversations in a form it cannot list');
};

const SILENT = {debug: () => undefined, info: () => undefined, warn: () => undefined, error: () => undefined};

const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

beforeAll(() => setLogger(SILENT));
afterAll(() => setLogger());

afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
});

describe('the conversation list on the websocket', () => {
  it("delivers the connecting user's conversations as one conversation_list, newest first, with wire times as ISO strings", async () => {
    const store = new InMemorySessionStore();
    const url = await startConfiguredEngine({
      provider: {type: 'mock'},
      prompt: {identity: 'test'},
      session: store,
      auth: {ws: async () => ({id: USER})},
      transport: {history: {enabled: true}},
    });
    const {client, seen, sessionId} = await openAndSettle(url);
    seed(store, 'earlier', USER, JAN);
    seed(store, 'later', USER, FEB);
    seed(store, 'someone-elses', SOMEONE_ELSE, FEB);

    const beforeRequest = seen.length;
    client.send(JSON.stringify({type: 'list_conversations'}));
    await until(seen, frame => frame.type === 'conversation_list' || frame.type === 'error', 'the answer to the list request');
    await settle(client, seen);

    const lists = seen.filter(frame => frame.type === 'conversation_list');
    const rows = lists[0]?.conversations ?? [];
    const timesAreIso = rows.every(row => ISO.test(row.createdAt) && ISO.test(row.updatedAt));

    expect({
      pushedBeforeAnyoneAsked: seen.slice(0, beforeRequest).some(frame => frame.type === 'conversation_list'),
      answered: lists.length,
      withErrors: seen.filter(frame => frame.type === 'error').map(frame => frame.code),
      newestFirst: rows.map(row => row.sessionId),
      theConversationItSitsIn: {row: rows[0]?.sessionId, entries: rows[0]?.entryCount},
      timesAreIso,
      closesLikeATurn: seen.some(frame => frame.type === 'stream_end'),
    }).toEqual({
      pushedBeforeAnyoneAsked: false,
      answered: 1,
      withErrors: [],
      newestFirst: [sessionId, 'later', 'earlier'],
      theConversationItSitsIn: {row: sessionId, entries: 0},
      timesAreIso: true,
      closesLikeATurn: false,
    });
  });

  it("answers a frame naming another user with the connecting user's own list, paging by the window the frame sent", async () => {
    const store = new RecordingStore();
    const url = await startEngine({sessionStore: store, history: {enabled: true}});
    const {client, seen} = await openAndSettle(url);
    seed(store, 'older', USER, JAN);
    seed(store, 'middle', USER, FEB);
    seed(store, 'newest', USER, MARCH);
    seed(store, 'someone-elses', SOMEONE_ELSE, MARCH);

    client.send(JSON.stringify({type: 'list_conversations', userId: SOMEONE_ELSE, limit: 1}));
    const first = await until(seen, frame => frame.type === 'conversation_list' || frame.type === 'error', 'a first page');
    const [head] = first.conversations ?? [];
    client.send(
      JSON.stringify({
        type: 'list_conversations',
        userId: SOMEONE_ELSE,
        limit: 1,
        before: {updatedAt: head?.updatedAt, sessionId: head?.sessionId},
      })
    );
    await until(seen, frame => frame.type === 'conversation_list' && frame !== first, 'a second page');
    await settle(client, seen);

    const pages = seen
      .filter(frame => frame.type === 'conversation_list')
      .map(frame => (frame.conversations ?? []).map(row => row.sessionId));
    const asked = store.asked.map(call => ({userId: call.userId, limit: call.options?.limit, before: call.options?.before}));

    expect({pages, asked}).toEqual({
      pages: [
        ['newest'],
        ['middle'],
      ],
      asked: [
        {userId: USER, limit: 1, before: undefined},
        {userId: USER, limit: 1, before: {updatedAt: MARCH, sessionId: 'newest'}},
      ],
    });
  });

  it('answers UNSUPPORTED wherever it cannot answer, and never with a list or an empty one', async () => {
    // Off by default: the deployer never turned history on.
    const off = await startEngine({sessionStore: storeHolding([['kept', USER, JAN]])});
    const refused = await openAndSettle(off);
    refused.client.send(JSON.stringify({type: 'list_conversations'}));
    await until(refused.seen, frame => frame.type === 'error', 'the answer to a refused list');
    await settle(refused.client, refused.seen);

    // On, against a store written before lists existed: it has no listFor to answer with.
    const withoutListFor = await startEngine({sessionStore: fiveMemberStore, history: {enabled: true}});
    const unlisted = await openAndSettle(withoutListFor);
    unlisted.client.send(JSON.stringify({type: 'list_conversations'}));
    await until(unlisted.seen, frame => frame.type === 'error', 'the answer over a store that cannot list');
    await settle(unlisted.client, unlisted.seen);

    const answered = (seen: Frame[]): {codes: string[]; lists: number; rows: number} => ({
      codes: seen.filter(frame => frame.type === 'error').map(frame => frame.code),
      lists: seen.filter(frame => frame.type === 'conversation_list').length,
      rows: seen.filter(frame => frame.type === 'conversation_list').flatMap(frame => frame.conversations ?? []).length,
    });

    expect({offByDefault: answered(refused.seen), withoutAListFor: answered(unlisted.seen)}).toEqual({
      offByDefault: {codes: ['UNSUPPORTED'], lists: 0, rows: 0},
      withoutAListFor: {codes: ['UNSUPPORTED'], lists: 0, rows: 0},
    });
  });

  it('answers UNSUPPORTED for a store that throws StoreCannotList, as the misconfiguration it is', async () => {
    const url = await startEngine({sessionStore: new CannotListStore(), history: {enabled: true}});
    const {client, seen} = await openAndSettle(url);
    client.send(JSON.stringify({type: 'list_conversations'}));
    await until(seen, frame => frame.type === 'error', 'the answer to a misconfigured store');
    await settle(client, seen);

    expect({
      codes: seen.filter(frame => frame.type === 'error').map(frame => frame.code),
      lists: seen.filter(frame => frame.type === 'conversation_list').length,
    }).toEqual({codes: ['UNSUPPORTED'], lists: 0});
  });

  it('answers SERVER_ERROR when the store fails, without carrying its detail, and keeps the socket', async () => {
    // Captured for this test alone: the criterion is the log line written beside the frame.
    const logged: Array<Record<string, unknown>> = [];
    setLogger({
      debug: () => undefined,
      info: () => undefined,
      warn: () => undefined,
      error: (category, message, fields) => void logged.push({category, message, ...fields}),
    });
    try {
      const url = await startEngine({sessionStore: new FailingStore(), history: {enabled: true}});
      const {client, seen, sessionId} = await openAndSettle(url);
      client.send(JSON.stringify({type: 'list_conversations'}));
      await until(seen, frame => frame.type === 'error', 'the answer to a failing store');
      // The ping after the failure is answered only on a socket the error did not close.
      await settle(client, seen);

      const answered = seen
        .filter(frame => frame.type === 'error')
        .map(frame => ({code: frame.code, carriesStoreDetail: /db-prod|mongo|cluster/.test(frame.message ?? '')}));

      expect({
        answered,
        logged: {withSession: logged.some(line => line.sessionId !== undefined), storeDetail: logged.some(line => JSON.stringify(line).includes('db-prod'))},
      }).toEqual({
        answered: [{code: 'SERVER_ERROR', carriesStoreDetail: false}],
        logged: {withSession: true, storeDetail: false},
      });
    } finally {
      setLogger(SILENT);
    }
  });

  it("answers a list request while a turn streams, before that turn's stream_end", async () => {
    const hold = deferred();
    const streaming: ChatOrchestrator = {
      processMessage: async () => 'hi',
      async *processMessageStream(): AsyncGenerator<MessageChunk> {
        yield {type: 'text', text: 'half an answer'};
        await hold.until;
        yield {type: 'stop', stopReason: 'end_turn'};
      },
    };
    const url = await startEngine({sessionStore: new InMemorySessionStore(), history: {enabled: true}}, streaming);
    const {client, seen} = await openAndSettle(url);

    client.send(JSON.stringify({type: 'user_message', content: 'a question worth a long answer'}));
    await until(seen, frame => frame.type === 'entry_delta', 'the streaming answer to start');
    client.send(JSON.stringify({type: 'list_conversations'}));
    await until(seen, frame => frame.type === 'conversation_list' || frame.type === 'error', 'the answer to the list request');
    hold.release();
    await until(seen, frame => frame.type === 'stream_end', 'the turn to end');

    const order = seen.map(frame => frame.type);
    expect({
      listBeforeStreamEnd: order.indexOf('conversation_list') < order.indexOf('stream_end'),
      answers: seen.filter(frame => frame.type === 'conversation_list').map(frame => (frame.conversations ?? []).length),
    }).toEqual({listBeforeStreamEnd: true, answers: [1]});
  });

  it('refuses a frame whose window is malformed, naming the field', async () => {
    const url = await startEngine({sessionStore: new InMemorySessionStore(), history: {enabled: true}});
    const {client, seen} = await openAndSettle(url);

    const malformed = [
      {type: 'list_conversations', limit: 0},
      {type: 'list_conversations', limit: 201},
      {type: 'list_conversations', limit: 1.5},
      {type: 'list_conversations', limit: '10'},
      {type: 'list_conversations', before: 'not a date'},
      {type: 'list_conversations', before: {updatedAt: JAN}},
    ];
    for (const frame of malformed) client.send(JSON.stringify(frame));
    await settle(client, seen);

    const refusals = seen
      .filter(frame => frame.type === 'error')
      .map(frame => ({code: frame.code, names: ['limit', 'before'].find(field => (frame.message ?? '').includes(field))}));

    expect(refusals).toEqual([
      {code: 'INVALID_MESSAGE', names: 'limit'},
      {code: 'INVALID_MESSAGE', names: 'limit'},
      {code: 'INVALID_MESSAGE', names: 'limit'},
      {code: 'INVALID_MESSAGE', names: 'limit'},
      {code: 'INVALID_MESSAGE', names: 'before'},
      {code: 'INVALID_MESSAGE', names: 'before'},
    ]);
  });

  it('rejoins a conversation by an id taken from the list, through the resume path resume enables', async () => {
    const url = await startEngine({
      sessionStore: storeHolding([
        ['stored-one', USER, JAN],
        ['stored-two', USER, FEB],
      ]),
      resume: {enabled: true},
      history: {enabled: true},
    });
    const {client, seen} = await openAndSettle(url);
    client.send(JSON.stringify({type: 'list_conversations'}));
    const listed = await until(seen, frame => frame.type === 'conversation_list' || frame.type === 'error', 'the conversation list');
    const row = (listed.conversations ?? []).find(candidate => candidate.sessionId === 'stored-one');

    client.close();
    await once(client, 'close');
    const again = await openAndSettle(`${url}?sessionId=${row?.sessionId}`);
    await settle(again.client, again.seen);

    expect({
      tookTheIdFrom: row?.sessionId,
      resumed: again.seen[0]?.resumed,
      entryCount: again.seen[0]?.entryCount,
      replay: again.seen.filter(frame => frame.type === 'entry_upsert').map(frame => frame.entry?.content),
    }).toEqual({
      tookTheIdFrom: 'stored-one',
      resumed: true,
      entryCount: 1,
      replay: ['what stored-one asked'],
    });
  });
});

